import * as counter from "./counter.js";

export const registry = {
    counter: counter,
    "alias/counter": counter,
};

export function describe() {
    const ns = registry["counter"];
    return `${ns.count} ${ns.legacy} ${ns.label} ${typeof ns.bump} ${typeof ns}`;
}

export function bumpThrough() {
    registry.counter.bump();
}

export function same() {
    return registry.counter === registry["alias/counter"];
}

function assign(target, key, value) {
    try {
        target[key] = value;
    } catch (error) {
        return `${error.name}: ${error.message}`;
    }
    return "no error";
}

function lookup(name) {
    return registry[name];
}

export function writeThrough() {
    return assign(lookup("counter"), "count", 5);
}

export function addThrough() {
    return assign(lookup("alias/counter"), "extra", 5);
}
